import cmath, math
from typing import Tuple
Matrix2 = Tuple[Tuple[complex, complex], Tuple[complex, complex]]

def mul(M: Matrix2, N: Matrix2) -> Matrix2:
    return ((M[0][0]*N[0][0]+M[0][1]*N[1][0], M[0][0]*N[0][1]+M[0][1]*N[1][1]),
            (M[1][0]*N[0][0]+M[1][1]*N[1][0], M[1][0]*N[0][1]+M[1][1]*N[1][1]))

for t in [1+0j, 1j, cmath.exp(2j*math.pi/5)]:
    B1: Matrix2 = ((-t, 1+0j), (0j, 1+0j)); B2: Matrix2 = ((1+0j, 0j), (t, -t))
    P = mul(B1, B2); FT = mul(mul(P, P), P)
    print(f't={t:.3f}: (B1B2)^3 = {FT};  trace = {FT[0][0]+FT[1][1]:.3f}; 2t^3 = {2*t**3:.3f}')

